import java.io.*;
import java.util.*;

public class E {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        String nextLine() {
            String line = "";
            try {
                line = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return line;
        }
    }

    static FastReader reader = new FastReader();
    static PrintWriter writer = new PrintWriter(System.out);

    private static int[] inputIntArray(int size) {
        int[] array = new int[size];
        for (int i = 0; i < size; i++) {
            array[i] = reader.nextInt();
        }
        return array;
    }

    private static int[][] inputIntMatrix(int n, int m) {
        int[][] matrix = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = reader.nextInt();
            }
        }
        return matrix;
    }

    private static long[] inputLongArray(int n) {
        long[] array = new long[n];
        for (int i = 0; i < n; i++) {
            array[i] = reader.nextLong();
        }
        return array;
    }

    private static long[][] inputLongMatrix(int n, int m) {
        long[][] matrix = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = reader.nextLong();
            }
        }
        return matrix;
    }

    private static int getNextInt() {
        return reader.nextInt();
    }

    private static long getNextLong() {
        return reader.nextLong();
    }

    private static String getNextString() {
        return reader.next();
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static int binarySearch(List<Long> list, long val, int start) {
        int left = start, right = list.size() - 1;
        int res = list.size();

        while (left <= right) {
            int mid = (left + right) / 2;
            if (list.get(mid) > val) {
                if (mid == 0) return mid;
                if (list.get(mid - 1) <= val) return mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return res;
    }

    static long process(List<Node> nodes, long[] b, int index) {
        if (index == 3) return 0;

        Node node = nodes.get(index);
        int bIdx = node.ind - 1;
        if (bIdx == -1) bIdx = 2;

        long min1 = Math.min(node.val, b[bIdx]);
        node.val -= min1;
        b[bIdx] -= min1;

        long min2 = Math.min(node.val, b[node.ind]);
        node.val -= min2;
        b[node.ind] -= min2;

        long res1 = node.val + process(nodes, b, index + 1);
        node.val += min1 + min2;
        b[bIdx] += min1;
        b[node.ind] += min2;

        // second scenario
        node = nodes.get(index);
        bIdx = node.ind - 1;
        if (bIdx == -1) bIdx = 2;

        long min3 = Math.min(node.val, b[node.ind]);
        node.val -= min3;
        b[node.ind] -= min3;

        long min4 = Math.min(node.val, b[bIdx]);
        node.val -= min4;
        b[bIdx] -= min4;

        long res2 = node.val + process(nodes, b, index + 1);
        node.val += min3 + min4;
        b[bIdx] += min4;
        b[node.ind] += min3;

        return Math.min(res1, res2);
    }

    public static void main(String[] args) {
        StringBuilder output = new StringBuilder();
        int t = 1;
        while (t-- > 0) {
            int n = getNextInt();
            long[] a = inputLongArray(3);
            long[] b = inputLongArray(3);

            long maxVal = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
            long minVal = Math.max(0, a[0] + b[1] - n) + Math.max(0, a[1] + b[2] - n) + Math.max(0, a[2] + b[0] - n);
            output.append(minVal).append(" ").append(maxVal).append("\n");
        }
        writer.print(output.toString());
        writer.flush();
    }

    static class Node {
        int ind;
        long val;

        public Node(int ind, long val) {
            this.ind = ind;
            this.val = val;
        }
    }
}
